{
  "findings": [
    {
      "check_id": "CKV_GCP_32",
      "title": "Ensure 'Block Project-wide SSH keys' is enabled for VM instances",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The instance is not configured to block project-wide SSH keys, potentially allowing unauthorized access."
    },
    {
      "check_id": "CKV_GCP_31",
      "title": "Ensure that instances are not configured to use the default service account with full access to all Cloud APIs",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The instance uses the default service account with full 'cloud-platform' scope, potentially granting excessive permissions."
    },
    {
      "check_id": "CKV_GCP_40",
      "title": "Ensure that Compute instances do not have public IP addresses",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The instance has a public IP address due to the presence of an 'access_config' block, potentially exposing it to unauthorized access."
    },
    {
      "check_id": "CKV_GCP_35",
      "title": "Ensure 'Enable connecting to serial ports' is not enabled for VM Instance",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The instance has serial port access enabled, potentially allowing unauthorized access."
    }
  ],
  "patched_code": "resource \"google_compute_instance\" \"backup_orchestration_engine\" {\n  name         = \"enterprise-disaster-recovery-orchestration-platform-compute-orchestration\"\n  machine_type = \"e2-medium\"\n  zone         = \"${var.primary_region}-a\"\n  boot_disk {\n    initialize_params {\n      image = \"debian-cloud/debian-11\"\n      size  = 50\n    }\n  }\n  network_interface {\n    network    = google_compute_network.dr_vpc.id\n    subnetwork = google_compute_subnetwork.management_subnet.id\n  }\n  service_account {\n    email  = \"123456789-compute@developer.gserviceaccount.com\"\n    scopes = [\"https://www.googleapis.com/auth/cloud-platform.read-only\"]\n  }\n  metadata = {\n    serial-port-enable = false\n    startup-script     = file(\"${path.module}/scripts/orchestration-startup.sh\")\n    block-project-ssh-keys = true\n  }\n  tags = [\"dr-internal\", \"orchestration-engine\"]\n  depends_on = [\n    google_storage_bucket.primary_backup_storage,\n    google_sql_database_instance.recovery_database\n  ]\n}\n",
  "fix_summary": "Removed public IP address by deleting 'access_config', restricted service account scope to read-only, disabled serial port access, and enabled block project-wide SSH keys."
}
